from PIL import Image
im=Image.open('chess_board.png').convert('RGB'); px=im.load()
cells=[]
for r in range(8):
  for c in range(8):
    bg=(240,217,181) if (r+c)%2==0 else (181,136,99)
    # occupancy meaningful >80
    pts=[]
    for y in range(80):
      for x in range(80):
        p=px[c*80+x,r*80+y]
        if sum(abs(p[i]-bg[i]) for i in range(3))>80:
          pts.append((x,y))
    if len(pts)>100:
      cells.append((r,c,len(pts)))
print(len(cells),[ (chr(97+c)+str(8-r),n) for r,c,n in cells])
# produce binary mask threshold 35 diff, then compare pair IoU after maybe excluding coordinate labels by only bbox main? labels small.
masks={}
for r,c,n in cells:
    bg=(240,217,181) if (r+c)%2==0 else (181,136,99)
    m=set()
    for y in range(80):
      for x in range(80):
        p=px[c*80+x,r*80+y]
        if sum(abs(p[i]-bg[i]) for i in range(3))>35:
          m.add((x,y))
    masks[(r,c)]=m
for i,(r,c,n) in enumerate(cells):
  sims=[]
  for (r2,c2,n2) in cells[i+1:]:
    a=masks[(r,c)]; b=masks[(r2,c2)]
    inter=len(a&b); union=len(a|b)
    sim=inter/union if union else 0
    if sim>0.82: sims.append((sim,chr(97+c2)+str(8-r2)))
  if sims:
    print(chr(97+c)+str(8-r), sorted(sims,reverse=True))
