from PIL import Image
im=Image.open('chess_board.png').convert('RGB'); px=im.load()
cells=[]
for r in range(8):
  for c in range(8):
    bg=(240,217,181) if (r+c)%2==0 else (181,136,99)
    n=sum(1 for y in range(80) for x in range(80) if sum(abs(px[c*80+x,r*80+y][i]-bg[i]) for i in range(3))>80)
    if n>100: cells.append((r,c,n))
masks={}
for r,c,n in cells:
    bg=(240,217,181) if (r+c)%2==0 else (181,136,99)
    masks[(r,c)]={(x,y) for y in range(80) for x in range(80) if sum(abs(px[c*80+x,r*80+y][i]-bg[i]) for i in range(3))>35}
for r,c,n in cells:
  sims=[]
  for (r2,c2,n2) in cells:
    if (r,c)==(r2,c2): continue
    a=masks[(r,c)]; b=masks[(r2,c2)]
    sim=len(a&b)/len(a|b)
    sims.append((sim,chr(97+c2)+str(8-r2)))
  tops=sorted(sims,reverse=True)[:4]
  print(chr(97+c)+str(8-r), ', '.join(f'{n2}:{s:.3f}' for s,n2 in tops))
